using System.Collections;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;
using SystemWorld;
public class FoundationPlayTests {
 static WorldEnvelope Init()=>new WorldEnvelope{protocolVersion=WorldCodec.Version,type="WORLD_INIT",messageId="init1",timestamp="2026-11-02T10:00:00.000Z",playerId="p1",profileGeneration=0,sessionId="s1",stateRevision=0,payload=Newtonsoft.Json.Linq.JObject.Parse("{\"hostBuildSha\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\",\"quality\":\"LOW\"}")};
 [UnityTest] public IEnumerator FocusAndBackgroundClearInput(){var world=WorldFoundation.Create();yield return null;world.SetMovement(Vector2.one);world.SendMessage("OnApplicationPause",true);Assert.AreEqual(Vector2.zero,world.MovementInput);world.SetMovement(Vector2.one);world.SendMessage("OnApplicationFocus",false);Assert.AreEqual(Vector2.zero,world.MovementInput);world.SetMovement(Vector2.one);yield return null;Assert.AreEqual(Vector2.zero,world.MovementInput,"Missing touch ID must recover");Object.Destroy(world.gameObject);yield return null;}
 [UnityTest] public IEnumerator HostPauseClearsInputBeforeResume(){var world=WorldFoundation.Create();yield return null;var bridge=world.Bridge;bridge.Accept(Init());world.SetMovement(Vector2.one);var e=Init();e.type="WORLD_PAUSE";e.messageId="pause1";e.payload=Newtonsoft.Json.Linq.JObject.Parse("{\"reason\":\"BACKGROUND\"}");bridge.Accept(e);Assert.AreEqual(Vector2.zero,world.MovementInput);e.type="WORLD_RESUME";e.messageId="resume1";bridge.Accept(e);yield return null;Assert.AreEqual(Vector2.zero,world.MovementInput);Object.Destroy(world.gameObject);yield return null;}
 [UnityTest] public IEnumerator SceneRunsAndGravityLands(){var world=WorldFoundation.Create();yield return new WaitForSeconds(1);Assert.NotNull(world.Motor);Assert.AreEqual("Idle",world.MotionState);Assert.Less(world.Motor.transform.position.y,.3f);Assert.Greater(world.Motor.transform.position.y,-.2f);Assert.NotNull(Camera.main);world.SetQuality("LOW");Assert.AreEqual(30,Application.targetFrameRate);Assert.AreEqual("LOW",world.Quality);world.SetQuality("HIGH");Assert.AreEqual(60,Application.targetFrameRate);Object.Destroy(world.gameObject);yield return null;}
 [UnityTest] public IEnumerator InjectedStickWalksThenRuns(){var world=WorldFoundation.Create();yield return null;world.SetMovement(new Vector2(0,.4f),true);yield return new WaitForSeconds(.2f);Assert.AreEqual("Walk",world.MotionState);Assert.Greater(world.Motor.transform.position.z,-5f);world.SetMovement(new Vector2(0,1),true);yield return new WaitForSeconds(.2f);Assert.AreEqual("Run",world.MotionState);Object.Destroy(world.gameObject);yield return null;}
 [UnityTest] public IEnumerator PillarsBlockForwardLocomotion(){var world=WorldFoundation.Create();yield return null;world.SetMovement(new Vector2(0,1),true);yield return new WaitForSeconds(3);Assert.Less(world.Motor.transform.position.z,6.7f);Assert.Greater(world.Motor.transform.position.z,0f);Object.Destroy(world.gameObject);yield return null;}
 [UnityTest] public IEnumerator PortalCommandIsHostOnlyAndRequiresProximity(){var world=WorldFoundation.Create();yield return null;string action=null;world.Bridge.CommandPrepared+=e=>action=(string)e.payload["action"]+"|"+e.payload["panel"];world.Bridge.Accept(Init());Assert.False(world.NearPortal);Assert.False(world.InteractPortal());Assert.AreEqual("REQUEST_SNAPSHOT",action==null?null:action.Split('|')[0]);world.Motor.enabled=false;world.Motor.transform.position=new Vector3(0,.1f,8.2f);world.Motor.enabled=true;yield return null;Assert.True(world.NearPortal);Assert.True(world.InteractPortal());Assert.AreEqual("OPEN_PANEL|QUESTS",action);Object.Destroy(world.gameObject);yield return null;}
 [UnityTest] public IEnumerator CameraFollowsAvatarWithoutEnteringController(){var world=WorldFoundation.Create();yield return null;var cam=Camera.main;Assert.NotNull(cam);world.SetMovement(new Vector2(1,0),true);yield return new WaitForSeconds(.4f);Assert.Greater(Vector3.Distance(cam.transform.position,world.Motor.transform.position),1.2f);Object.Destroy(world.gameObject);yield return null;}
}
